-- Materialize the frozen BOB / Thule / Veer travel-system audit.
-- Source artifact: reports/travel-system-inventory/BTV_FROZEN_V1.md
-- Input CSV: reports/travel-system-inventory/TMBC_Compatibility_Row_Audit_BOB_Thule_Veer.csv
-- Frozen totals: 392 audited rows = 87 manufacturer-listed + 30 should-work + 202 unknown + 19 identity dedup + 54 excluded products.
-- Public materialization: remove the audited BTV block, then insert only the 117 consumer-visible rows.

CREATE TEMP TABLE _btv_audit_pairs (
  stroller_brand text NOT NULL,
  stroller_model text NOT NULL,
  car_seat_brand text NOT NULL,
  car_seat_model text NOT NULL
) ON COMMIT DROP;


DELETE FROM "Compatibility" AS compat
USING _btv_audit_pairs AS audit
INNER JOIN "Stroller" AS stroller
  ON LOWER(stroller."brand") = LOWER(audit.stroller_brand)
 AND LOWER(stroller."model") = LOWER(audit.stroller_model)
INNER JOIN "CarSeat" AS seat
  ON LOWER(seat."brand") = LOWER(audit.car_seat_brand)
 AND LOWER(seat."model") = LOWER(audit.car_seat_model)
WHERE compat."strollerId" = stroller."id"
  AND compat."carSeatId" = seat."id";

CREATE TEMP TABLE _btv_visible_pairs (
  compatibility_id text NOT NULL,
  stroller_brand text NOT NULL,
  stroller_model text NOT NULL,
  car_seat_brand text NOT NULL,
  car_seat_model text NOT NULL,
  compatibility_type text NOT NULL,
  adapter_required boolean NOT NULL,
  adapter_type text,
  adapter_sku text,
  adapter_url text,
  notes text NOT NULL,
  confidence text NOT NULL
) ON COMMIT DROP;

  compatibility_id, stroller_brand, stroller_model, car_seat_brand, car_seat_model,
  compatibility_type, adapter_required, adapter_type, adapter_sku, adapter_url, notes, confidence
)
