  "id",
  "strollerId",
  "carSeatId",
  "compatibilityType",
  "adapterRequired",
  "adapterType",
  "adapterBabylistSku",
  "adapterBabylistUrl",
  "notes",
  "confidence",
  "createdAt",
  "updatedAt"
)
SELECT
  visible.compatibility_id,
  stroller."id",
  seat."id",
  visible.compatibility_type::"CompatibilityType",
  visible.adapter_required,
  visible.adapter_type,
  visible.adapter_sku,
  visible.adapter_url,
  visible.notes,
  visible.confidence::"CompatibilityConfidence",
  CURRENT_TIMESTAMP,
  CURRENT_TIMESTAMP
FROM _btv_visible_pairs AS visible
INNER JOIN "Stroller" AS stroller
  ON LOWER(stroller."brand") = LOWER(visible.stroller_brand)
 AND LOWER(stroller."model") = LOWER(visible.stroller_model)
INNER JOIN "CarSeat" AS seat
  ON LOWER(seat."brand") = LOWER(visible.car_seat_brand)
 AND LOWER(seat."model") = LOWER(visible.car_seat_model)
ON CONFLICT ("strollerId", "carSeatId") DO UPDATE
SET
  "compatibilityType" = EXCLUDED."compatibilityType",
  "adapterRequired" = EXCLUDED."adapterRequired",
  "adapterType" = EXCLUDED."adapterType",
  "adapterBabylistSku" = EXCLUDED."adapterBabylistSku",
  "adapterBabylistUrl" = EXCLUDED."adapterBabylistUrl",
  "notes" = EXCLUDED."notes",
  "confidence" = EXCLUDED."confidence",
  "updatedAt" = CURRENT_TIMESTAMP;
